// start, preflight, route checkpoints, cutscene checkpoints, tactics, commentary, pickups
const DETAILS = {
1: ['Start of your existing Roxas recording.',
  ['Keep the original footage and its actual duration; these opening boundaries are a reconstruction.', 'Check the choice of weapon and retain the explanation you gave viewers.'],
  ['Open on the town introduction and the photograph mystery; establish the four friends before advancing.', 'Follow the investigation through town, fight Seifer, and pursue the strange thief toward the woods.', 'Play the mandatory odd jobs and the station sequence without repeating jobs for extra money.', 'On the following day, follow the mysterious girl and complete the awakening tutorial.', 'Fight the Dusks and Twilight Thorn, then retain the return to town.'],
  ['The opening movie and Roxas’s dreams.', 'Photograph mystery, station interruption, and Naminé’s first appearances.', 'The complete awakening and post–Twilight Thorn scenes.'],
  [['Twilight Thorn','Follow each reaction prompt as the arena shifts. Once regular combat resumes, clear dangerous Dusks and watch the boss rather than swinging through its attacks.']],
  ['Introduce the difference between the player’s knowledge and Roxas’s confusion.', 'Keep the mystery intact: do not explain Days or Xion yet.'], 'No collectible detour required.'],
2: ['The Struggle tournament opening in your recorded footage.',
  ['Use your existing episode cut; do not re-record to match this reconstruction.', 'Explain the orb rules once before the first match.'],
  ['Speak to the tournament organizer at the Sandlot and face Hayner.', 'Continue to Vivi; keep the transition from the match into the Nobody interruption.', 'Defeat Axel and let the entire conversation finish before resuming the tournament.', 'Finish the Setzer match and watch the friends’ celebration.', 'Follow Day 5 through Sunset Terrace and Sunset Hill, completing the required Seven Wonders investigations.', 'Retain the mansion-related discoveries and stop at the Day 6 transition.'],
  ['The interruption during Vivi’s match and Axel recognizing Roxas.', 'The tournament aftermath and the friends at the clock tower.', 'The Seven Wonders’ unsettling resolutions.'],
  [['Struggle','A lead in orbs wins when time expires. Collect dropped orbs and avoid losing your lead to unnecessary trades.'],['Axel I','Guard his approach, then answer with a short combo. His pauses are safer openings than chasing him around the arena.']],
  ['Contrast the friends’ normal summer with Roxas’s increasingly private experiences.'], 'Retain whichever tournament reward your recorded result earned.'],
3: ['Day 6, before entering the Old Mansion.',
  ['Keep the existing recording’s start and end intact.', 'Allow the concluding dialogue to breathe; avoid narrating over Roxas’s farewell.'],
  ['Cross town and the woods to reach the Old Mansion.', 'Visit the White Room and Library and follow the clues that open the basement.', 'Watch the computer-room revelation and the collapse of Roxas’s normal life.', 'Clear the basement Nobodies and enter the second Axel fight.', 'After winning, follow the corridor to the Pod Room without a treasure detour.', 'Keep the final Roxas/Sora transition in full.'],
  ['Naminé’s explanation and DiZ’s intervention.', 'Roxas confronting the computer and Axel’s farewell.', 'Roxas finding Sora and the end of his summer.'],
  [['Axel II','This is Roxas’s dual-wielding showcase. Follow the reaction sequence when Axel leaves the center; avoid treating the burning arena edge as a safe retreat.']],
  ['Discuss how the tutorial gives Roxas a life before taking it away.', 'Save conclusions about his complete past for the Days watch.'], 'No preparation carries over through a special grind requirement.'],
4: ['Sora awakening; use your actual recorded boundary.',
  ['Verify that this footage includes the Hollow Bastion gate defense before Part 5.', 'If that defense remains unfinished, add it as the opening continuation before departing for China.'],
  ['Reunite Sora, Donald, and Goofy and visit Twilight Town’s friends.', 'Complete the station encounter, receive the travel help, and board the train.', 'Ascend the Mysterious Tower and watch Yen Sid’s briefing.', 'Visit the fairies, receive the clothes and Valor Form, then depart in the gummi ship.', 'Land in Hollow Bastion and meet Yuffie and the Restoration Committee at Merlin’s House.', 'Join Leon at the Bailey, defend the gate, and watch the Organization introduction.', 'End only once the first Disney-world routes are available.'],
  ['Sora’s farewell to Twilight Town.', 'Yen Sid’s full explanation and the new-clothes sequence.', 'The Restoration Committee, Organization arrival, and world-route opening.'],
  [['Bailey defense','Watch both the enemies and the gate’s condition. Intercept enemies reaching the objective instead of chasing the farthest target.'],['Valor introduction','Keep Goofy available to transform. Valor cannot cast Cure, so explain why items still matter.']],
  ['Connect Sora’s unexplained sadness to the opening without jumping ahead to Days.'], 'Valor Form and the early Hollow Bastion magic rewards.'],
5: ['World Map; choose the Land of Dragons route.',
  ['Restock Potions and equip Guard and useful combo abilities.', 'Keep Goofy in the active party when you intend to demonstrate Valor; Ping occupies the world-partner slot.', 'Record the first gummi route once; skip score and treasure replays.'],
  ['Land at the Bamboo Grove, meet Ping and Mushu, then walk into the Encampment.', 'Complete the opening camp defense and accept all three of Shang’s assignments.', 'Clear Surprise Attack, Ambush, and Search; use Fire on tents when searching for hidden enemies.', 'Follow the Checkpoint to Mountain Trail. Break the obstructions and preserve the morale gauge.', 'Reach the Village, enter the Village Cave, and clear the ambush before returning outside.', 'Watch the ruined-village scenes, climb the Ridge and Summit, and complete the mountain swarm.', 'After Mulan’s identity is revealed, return through the Checkpoint to the Imperial City.', 'Defend the palace gate, defeat Shan-Yu, and watch the Emperor and gateway scenes.'],
  ['Ping’s introduction and Shang accepting the party.', 'The village destruction, avalanche, and identity reveal.', 'The Emperor’s rescue and the entire world-ending scene.'],
  [['Morale missions','The meter is your real failure condition. Collect the drops that sustain it and intercept enemies instead of sightseeing during a mission.'],['Shan-Yu + Hayabusa','Prioritize Heartless attacking the palace doors. Punish Shan-Yu after his swings; use the clash reaction when offered. Heal before attempting another combo.']],
  ['Explain why protecting an objective changes your usual target priority.', 'Discuss Mulan proving herself through action rather than her disguise.'], 'Hidden Dragon after the world clear; review its ability before equipping.'],
6: ['World Map; land in Beast’s Castle.',
  ['Bring Potions: Cure is the reward at the end of this visit.', 'Leave room for several short bosses and a long set of story scenes.', 'Do not spend time farming Gargoyle enemies or revisiting chests.'],
  ['Clear the opening Shadows and save in the Parlor.', 'Go upstairs through the East Wing to Belle’s Room and hear her concern about Beast.', 'Cross to the West Hall, move the sleeping Wardrobe carefully, and enter the Undercroft.', 'Defeat Thresholder and Possessor, then enter the Dungeon and meet the servants.', 'Open the Secret Passage with Cogsworth. Keep Lumière and Mrs. Potts together while lighting the lamps; restore Cogsworth as necessary.', 'Climb to the West Wing, enter Beast’s Room, and fight to bring him to his senses.', 'Return toward Belle’s Room and follow the alarm to the Ballroom.', 'Defeat Shadow Stalker and Dark Thorn; watch the reconciliation and gateway scenes.', 'Keep the forced return to Merlin’s House, but leave the book visit for Part 7.'],
  ['Belle’s account of Beast’s behavior and the servants explaining the curse.', 'Xaldin’s manipulation and Beast recognizing his mistake.', 'Belle’s rescue, the world ending, and Merlin’s summons.'],
  [['Thresholder / Possessor','Use the release reaction after damaging the door enemy, then focus the exposed Possessor.'],['Beast','Use Cogsworth’s reaction prompts to interrupt him. This is a rescue encounter, not a reason to exhaust your items.'],['Shadow Stalker → Dark Thorn','Watch which piece of scenery is possessed and release the enemy. The second phase follows immediately; use its chandelier reactions and retain enough HP for the transition.']],
  ['Let the audience see the castle route once; explain shortcuts on the return trip.', 'Discuss Xaldin exploiting fear rather than physically overpowering Beast.'], 'Cure after Dark Thorn; assign it to a shortcut immediately.'],
7: ['Merlin’s House before entering Pooh’s book.',
  ['Assign Cure and stock Ethers; explain that Cure drains the MP bar.', 'Plan the episode as a quiet opening followed by an Underworld escape.'],
  ['Enter the book, meet Pooh, and keep the interruption by the Heartless.', 'Recover the book outside and return inside to establish Pooh’s missing memories.', 'Finish Merlin’s dialogue, receive Chicken Little, and depart for Olympus.', 'Meet Meg at the Underworld Entrance; descend the Cave of the Dead via Passage and Inner Chamber.', 'Continue to Hades’ Chamber, meet Auron, and trigger Hades’ confrontation.', 'When the game makes clear Hades cannot be defeated here, escape with Auron through the enemy waves.', 'Defeat Cerberus at the exit and watch the transition to the surface.', 'Save at the Coliseum Vestibule after the introduction there.'],
  ['Pooh forgetting Sora and the Torn Pages setup.', 'Hades summoning Auron and Auron refusing him.', 'The escape, Cerberus’s entrance, and the Coliseum reunion.'],
  [['Hades escape','Do not keep attacking an invulnerable boss. Follow the escape route and use Auron’s assistance to clear the enemies blocking progress.'],['Cerberus','Stay aware of the side heads while approaching the center. Use the prompted reaction opportunity and heal after disengaging, not in the middle of an incoming bite.']],
  ['Introduce the Underworld curse as an actual limitation on the combat toolkit.'], 'Chicken Little summon; do not challenge Zexion yet.'],
8: ['Coliseum Vestibule after Cerberus.',
  ['Check Cure, Ethers, and your active party before descending again.', 'Keep the Olympus Stone sequence intact so the return of Drive access makes sense.'],
  ['Complete Phil’s required training and watch the Hydra threat develop.', 'Return to the Underworld and follow the Olympus Stone trail.', 'Traverse the Underworld Caverns toward the Atrium and clear Demyx’s water-clone timer.', 'Watch the Absent Silhouette explanation, then proceed to the Lock to rescue Meg.', 'Fight Pete through the rescue and timed follow-up sections.', 'Return to the surface, watch the Coliseum disaster, and enter the Hydra battle.', 'Complete every Hydra stage and retain the full world conclusion.'],
  ['Phil and Hercules, the stolen stone, and Demyx’s introduction.', 'Meg’s rescue and Hercules’s response to the destroyed Coliseum.', 'The gateway and post-Hydra resolution.'],
  [['Demyx’s clones','Attack the water forms and chain the available reaction attacks before the timer expires; this is not the later full duel.'],['Pete','Keep rescue objectives safe and punish after his attacks. Use the fight’s reactions rather than wasting a full MP bar against invulnerability.'],['Hydra','Follow Phil’s prompts for the ground phase and Pegasus’s prompts in the aerial phase. Change targets as heads become available.']],
  ['Contrast Hercules’s confidence with the pressure of protecting everyone.'], 'Hero’s Crest; examine its aerial-combo role.'],
9: ['Disney Castle Courtyard after the world unlock.',
  ['Give yourself time to watch Minnie and Maleficent’s scenes in full.', 'Make the Library Torn Page a mandatory route pickup.'],
  ['Cross the Courtyard and Colonnade to the Library; collect Torn Page 1.', 'Meet Minnie and escort her through the Audience Chamber.', 'Use her cooperation commands to clear attackers while steadily moving to the destination.', 'Enter the Hall of the Cornerstone and watch the corruption reveal.', 'Travel to Merlin in Hollow Bastion and let his return-to-castle scene play.', 'Enter Timeless River, speak to the original Pete, and complete his introductory fight.', 'At Cornerstone Hill, clear Building Site and Lilliput; save the remaining two windows for next time.'],
  ['Minnie’s explanation and Maleficent’s threat.', 'Merlin opening the door and the first black-and-white transformation.', 'The window scenes connecting the past to the castle’s problem.'],
  [['Minnie escort','Stay near Minnie when the cooperation prompt is available; clearing a path safely is more important than sprinting ahead.'],['Past Pete / window defenses','Use the introduced reaction commands and focus on enemies threatening each scenario’s objective. Hot Rod-style charges need caution, not a head-on combo.']],
  ['Call attention to the animation, sound, and character-design shift.'], 'Torn Page 1: Disney Castle Library.'],
10: ['Cornerstone Hill with two windows already complete.',
  ['Recap the two finished scenarios and name the two remaining ones.', 'Reserve time after the world ending for the first cup.'],
  ['Clear Scene of the Fire and Mickey’s House from Cornerstone Hill.', 'Follow Pete’s theft into the waterway and recover the Cornerstone from the steamboat.', 'Enter the final confrontation and fight Present Pete as the arena changes.', 'Watch both Petes’ conclusion, return to Disney Castle, and receive Wisdom Form.', 'Travel to Olympus, speak to Pain and Panic, and enter the ordinary Pain and Panic Cup.', 'Clear all ten rounds and show the reward before saving.'],
  ['Each remaining window’s story.', 'The two Petes arguing and the restoration of the Cornerstone.', 'The Disney Castle resolution and Wisdom unlock.'],
  [['Steamboat / Pete','Use the recovery and pursuit reactions in the boat sequence. During the final fight, respond to the changing arena hazards before committing to damage.'],['Pain and Panic Cup','Use the reduced-cost party Limits to manage groups. Against Leon and Yuffie, keep both visible and avoid getting pinned while focusing one target.']],
  ['Explain Wisdom’s movement and magic identity after it unlocks; do not promise to use it in a cup that restricts Drives.'], 'Wisdom Form; Pain and Panic Cup completion.'],
11: ['Underworld Entrance after Part 10’s cup; depart via the World Map for Atlantica before Port Royal.',
  ['Keep magic on shortcuts for the pirate weaknesses.', 'Begin with Atlantica immediately after the Timeless River episode. Only the tutorial and Swim This Way are available now; reserve the Magnet-gated story for Part 16. Allow extra time before Port Royal’s voyages.'],
  ['Visit Atlantica first: meet Ariel, Flounder, and Sebastian, complete the swimming tutorial, and clear Swim This Way with all its scenes. When the Magnet requirement appears, leave via the World Map for Port Royal; fight the Rampart pirates and follow the rescue through the Harbor.', 'Meet Jack and Will; board the Interceptor and choose the story destination.', 'Explore Isla de Muerta along the required path and protect the escape while the rescue develops.', 'Watch the shipboard betrayal and battle the pursuing pirates.', 'Complete the Interceptor defense and remove the gunpowder before time runs out.', 'Return to Isla de Muerta and note Larxene’s Rock Face portal without entering.', 'Proceed to the Treasure Heap, defeat Barbossa, and keep the curse’s resolution.'],
  ['Ariel’s reunion, the swimming lesson, Swim This Way, and the next-chapter Magnet prompt; then Jack’s introduction and the explanation of the cursed gold.', 'The rescue, betrayal, and Interceptor disaster.', 'Barbossa’s defeat, the lifted curse, and farewell.'],
  [['Swim This Way','Follow Sebastian’s rhythm prompts and complete the tutorial song. Do not attempt the next chapter before obtaining Magnet.'],['Cursed pirates','Move fights into moonlight. If attacks bounce off, fix the enemy’s position rather than spending more combos on an invulnerable target.'],['Barbossa / Illuminator','Maintain visibility by handling the Illuminator when it interferes. Watch the partner’s safety as well as Sora’s HP.']],
  ['Explain the world-specific invulnerability rule before the audience mistakes it for low damage.'], 'Atlantica tutorial and Swim This Way cleared; return in Part 16 for songs 2–3. Follow Port Royal’s story route only; leave Larxene for Part 31.'],
12: ['Agrabah’s first visit.',
  ['Keep both Fire and Blizzard accessible for the elemental finale.', 'Use the Cave’s saves to refill before trials; skip synthesis detours.'],
  ['Clear the arrival ambush with Iago and meet Jasmine at the Palace.', 'Find Aladdin and Abu, identify Jafar’s lamp, and negotiate at the Peddler’s Shop.', 'Exit through the Bazaar and Palace Walls toward the Cave of Wonders.', 'Guide Abu through the jewel mechanism and finish the Stone Guardian sequence.', 'Descend through the cave trials and clear the required timed Heartless room.', 'Return to town with the treasure and follow Pete to the finale.', 'Defeat the two elemental Lords and keep Genie’s reunion and world ending.'],
  ['Iago asking for trust and Aladdin’s restlessness.', 'The lamp trade and Pete’s involvement.', 'Genie’s return and the gateway.'],
  [['Cave trials','Focus the mission timer and required mechanisms; chest cleanup can wait until an encounter is over.'],['Volcanic / Blizzard Lords','Watch for opposite elemental vulnerabilities and use the smaller enemies’ reactions when available. Avoid casting the matching element into the boss.']],
  ['Explain why this is a focused story clear rather than a Cave treasure sweep.'], 'Genie summon after the ending.'],
13: ['Halloween Town’s first landing.',
  ['Check Potions/Ethers before the factory battle.', 'Keep the Halloween-to-Christmas transformation on-screen.'],
  ['Meet Jack in town and follow his Christmas preparations.', 'Cross the Graveyard and Hinterlands, then use the tree to reach Yuletide Hill.', 'Visit Santa’s House and follow Lock, Shock, and Barrel’s interference.', 'Return along the story route to the graveyard confrontation.', 'Defeat Prison Keeper, then head back to Christmas Town for Oogie’s takeover.', 'Climb the factory’s conveyor-belt encounter and defeat Oogie.', 'Watch the complete Christmas resolution and note the new Magnet spell.'],
  ['Jack presenting his Christmas plans and meeting Santa.', 'Maleficent reviving Oogie and his takeover.', 'Santa’s lesson and Jack’s farewell.'],
  [['Prison Keeper','Watch which child is currently influencing its attack pattern and punish after its committed moves. Use air combos only when you can land safely.'],['Oogie Boogie','Launch presents into the booth using the reaction prompt, then attack while he is exposed. Watch the conveyor hazards and switch lanes when prompted.']],
  ['Compare the two towns’ visual presentation without talking over Santa’s key scenes.'], 'Magnet after Oogie; needed for the early Atlantica progression.'],
14: ['Pride Lands first landing.',
  ['Expect Lion Sora’s separate moveset; normal Drive plans do not apply.', 'Flag the Oasis Torn Page before leaving with Simba.'],
  ['Meet Nala at the Elephant Graveyard and follow the Pride Rock introduction.', 'Cross the Savannah, Wildebeest Valley, Wastelands, and Jungle on the story route.', 'Reach the Oasis, meet Simba, and collect Torn Page 2.', 'Watch Simba’s hesitation and decision before returning to Pride Rock.', 'Defend Timon and Pumbaa in the den from the three hyenas.', 'Climb to the Peak for Scar, then preserve the full succession scenes.'],
  ['Nala’s appeal, Simba’s reunion, and his decision to return.', 'Scar’s accusation and transformation.', 'The Pride Lands’ first-visit ending.'],
  [['Hyenas','Protect the friends rather than running after a distant target. Use Lion Sora’s fast repositioning to intercept.',],['Scar','Learn the tells for his powered-up attack patterns and evade until the opening returns. Use Simba’s Limit deliberately and keep MP for healing.']],
  ['Talk about how the transformation changes traversal and the usual combat rhythm.'], 'Torn Page 2: Oasis.'],
15: ['World Map, ready for Sora’s middle Twilight Town visit.',
  ['Leave room for three distinct chapters rather than rushing their dialogue.', 'Keep the first two recovered Torn Pages available for the book visit.'],
  ['Revisit Twilight Town and meet the friends following the Sandlot encounter.', 'Follow the Kairi lead and complete the station conversation; obtain Oathkeeper and Limit Form.', 'Visit Merlin’s House and enter the book.', 'Complete Piglet’s House and Rabbit’s House once each, keeping the restored-memory scenes.', 'Exit the book and follow the Hollow Bastion computer discovery.', 'Cross the Bailey and Restoration Site to the Postern, then continue through the castle corridors.', 'Meet Tifa and Leon at Ansem’s Study, find the hidden computer, and watch the digitization.', 'Save in the Pit Cell after Tron’s introduction.'],
  ['The friends remembering Kairi and the station farewell.', 'Pooh recognizing each restored friend.', 'Tifa searching for Cloud and the party being pulled into the computer.'],
  [['Sandlot Nobodies','Use reactions and crowd control while protecting your space. After acquiring Limit Form, explain its solo-compatible recovery role in a safe follow-up fight.']],
  ['Keep this episode’s three chapters clear with short spoken transitions: Kairi, Pooh, then the computer.'], 'Oathkeeper, Limit Form; Piglet and Rabbit story clears.'],
16: ['Space Paranoids: Pit Cell with Tron.',
  ['Make space for Stitch’s charm pickup after returning to the real world.', 'Do not compress the password or Mickey scenes; this is a longer episode.'],
  ['Help Tron regain system access through the Canyon and return to the terminal.', 'Leave the computer to investigate Ansem’s Study and obtain the password.', 'Watch Mickey’s reunion, receive Master Form, and collect the Ukulele Charm near the computer.', 'Return to Space Paranoids and complete the Light Cycle escape.', 'Follow Tron through the required system rooms and energy collection objectives.', 'Defeat Hostile Program and watch the successful access to the data.', 'Return to Atlantica after the first visit in Part 11. Speak to Flounder and use Magnet to move the statue into Ariel’s Grotto.', 'With Magnet and five Drive bars available, finish Part of Your World and Under the Sea.'],
  ['Tron explaining the system and Mickey’s full reunion.', 'The password discovery and Master Form unlock.', 'Tron’s first-visit conclusion and Atlantica’s Part of Your World and Under the Sea chapter scenes.'],
  [['Light Cycle','Read the turn prompts and use the appropriate attack response; record a successful complete route rather than hiding the minigame.'],['Hostile Program','Collect its dropped clusters to activate the shutdown opportunity. Use the opening for damage, then disengage from the laser patterns.']],
  ['Explain Master Form’s Drive-orb experience rule when introducing it.', 'Treat Atlantica as a musical chapter; no need to apologize for watching it.'], 'Master Form, Stitch’s Ukulele Charm, five Drive bars; Atlantica chapters 2–3 (chapter 1 was completed in Part 11).'],
17: ['Return to Hollow Bastion’s computer-room storyline.',
  ['Restock before the town defense; save when the route offers a safe point.', 'Be ready to review Goofy’s equipment after he rejoins.', 'Collect the Crystal Fissure Torn Page before the army encounter.'],
  ['Watch the computer revelations and Mickey’s explanation before responding to the attack.', 'Leave through the corridors and Postern, clearing the required Heartless and Nobodies.', 'At the Bailey, watch the allied defense and confront Demyx.', 'Keep the complete aftermath involving Goofy; continue through the ally-assisted battles.', 'Reach Crystal Fissure, collect Torn Page 3, and restore Goofy’s equipment if needed.', 'Enter the Great Maw and defeat all 1,000 Heartless.', 'Watch every post-battle scene through the automatic World Map return.'],
  ['Ansem/Xehanort explanations, Sephiroth’s appearance, and the allies fighting.', 'Demyx’s confrontation, Goofy’s apparent injury, and reunion.', 'The Organization’s goal and the photograph/ice-cream clues.'],
  [['Demyx','Treat each clone timer as the immediate priority. Use the reactions offered during the water-form sections; defend between his committed attacks.'],['1,000 Heartless','Chain Rising Sun and Sparkle Ray to clear groups. Keep the complete successful battle and let the scale provide the spectacle.']],
  ['Let the revelations land before explaining what the Organization gains from Sora’s actions.'], 'Torn Page 3: Crystal Fissure; post-battle clues.'],
18: ['Land of Dragons second visit.',
  ['Equip movement and healing before following the stranger.', 'Leave a second chapter for the ordinary Cerberus Cup.'],
  ['Meet Mulan at the village and follow the hooded figure up the mountain.', 'Complete the Summit encounter and keep the familiar-weapon clue.', 'Return toward the Imperial City and clear the palace Nobody attack.', 'Visit the Throne Room and collect Torn Page 4.', 'Defeat Storm Rider over the city and watch the Emperor’s conclusion.', 'Travel to Olympus and clear all ten rounds of the ordinary Cerberus Cup.'],
  ['Mulan describing the spy and the stranger’s escape.', 'The palace explanation and Storm Rider’s arrival.', 'The second visit’s world ending.'],
  [['Storm Rider','Use the wind currents and reactions to reach its upper body; watch for the attacks that punish remaining in one place.'],['Cerberus Cup','Use the fast Drive recovery to stay aggressive within the timer. Do not carry the same assumptions into the later damage-point cup.']],
  ['Discuss the hooded stranger only to the extent the story has revealed.'], 'Torn Page 4: Throne Room; Cerberus Cup completion.'],
19: ['Beast’s Castle second visit.',
  ['Bring recovery items and keep defensive abilities equipped.', 'Allocate retry space for Xaldin without trimming the Belle/Beast scenes.'],
  ['Attend the dance setup in the Ballroom and clear the Nobody interruption.', 'Follow Beast through the West Wing after Xaldin’s provocation.', 'Watch Beast send the party away and note the Silhouette portal in his room.', 'Return and help restore his resolve; collect Rumbling Rose when available.', 'Pursue Xaldin through the castle and courtyard to the Bridge.', 'Watch Belle’s intervention, defeat Xaldin, and keep the reconciliation.'],
  ['The interrupted dance and Beast’s despair.', 'Belle taking action on the Bridge.', 'The complete farewell and world conclusion.'],
  [['Xaldin','Use Learn when offered to stock Jump attacks, then spend them in a safe window. Respect the wind barrier and avoid long ground strings into it. Watch the dragon-shaped wind attack and use available movement to avoid its sweep.']],
  ['Explain Learn/Jump before the successful attempt so the reaction sequence has context.'], 'Rumbling Rose; Marluxia portal reserved for Part 31.'],
20: ['Port Royal second visit.',
  ['Have offensive magic accessible for the medallion mechanic.', 'Remember the Feather Charm before leaving the Ship Graveyard.'],
  ['Meet Jack and investigate the renewed curse and Luxord’s arrival.', 'Fight the first Grim Reaper and follow the shipwreck aftermath.', 'Collect Peter Pan’s Feather Charm in the Ship Graveyard.', 'Sail to the marked destinations and defeat the Gamblers carrying stolen medallions.', 'Return to the Harbor, restore the chest, and defeat the second Grim Reaper.', 'Watch the world conclusion, then visit Pooh’s book for Kanga’s House.'],
  ['Luxord introducing the game and the party’s shipwreck.', 'The medallions restored and Port Royal’s farewell.', 'Kanga’s House and Pooh’s recovering memories.'],
  [['Grim Reaper II','Use magic to make it release medallions, collect them, and return them to the chest. Attack physically when the curse is removed; recover the objective again if it reabsorbs the coins.']],
  ['Make the curse cycle clear: extract, collect, return, then damage.'], 'Peter Pan’s Feather Charm; Magnera; Kanga’s House completion.'],
21: ['Agrabah second visit.',
  ['Keep Fire, Blizzard, and Thunder accessible for the ruins’ mechanisms.', 'Pick up the final Torn Page before leaving the Ruined Chamber.'],
  ['Investigate the Peddler’s remodeled shop and the released Jafar.', 'Follow Iago and ride Carpet into the desert ruins.', 'Complete the elemental mechanisms and clear the required Heartless waves.', 'Enter the Ruined Chamber and collect Torn Page 5.', 'Escape the ruins by carpet and return to Agrabah.', 'Fight Genie Jafar above the Palace, then watch the full conclusion.', 'Save at the Peddler’s Shop and point out Vexen’s portal for Part 31.'],
  ['The Peddler’s explanation and Iago’s role.', 'Jafar revealing the trap and the carpet escape.', 'The final reconciliation and gateway.'],
  [['Genie Jafar','Attack the exposed body sections to create a stagger, then follow the available reaction. Read the fire and debris patterns while repositioning on Carpet. Human-form Drives are not available here.']],
  ['Explain that the Torn Page is a required story-unlock pickup, not a completionist chest run.'], 'Torn Page 5: Ruined Chamber; Firaga and Wishing Lamp.'],
22: ['Halloween Town second visit.',
  ['Set aside a final chapter for Ursula after the Christmas story.', 'Check that Port Royal II is complete so Magnera is available.'],
  ['Investigate Santa’s missing presents and visit the factory.', 'Find Lock, Shock, and Barrel and complete the box-capture encounter.', 'Use the factory minigame to manufacture the replacement presents.', 'Set the trap, confront the Experiment, and defeat all its configurations.', 'Watch Jack and Sally’s complete conclusion and receive Decisive Pumpkin.', 'Travel to Atlantica and continue the Magnera-gated story through Ursula’s Revenge.'],
  ['Santa’s suspicions and the children’s explanation.', 'The Experiment’s motive and Jack/Sally’s ending.', 'Ariel’s bargain, Ursula’s confrontation, and its aftermath.'],
  [['The Experiment','Its detached parts change how the arena is threatened. Avoid tunneling on the main body when the other pieces are winding up attacks.'],['Ursula’s Revenge','This is a rhythm encounter. Follow the changing prompts and complete the repeated-input sections; no combat loadout changes are required.']],
  ['Compare the two villains’ ways of wanting something they do not have.'], 'Decisive Pumpkin; Mysterious Abyss after Ursula.'],
23: ['Pride Lands second visit.',
  ['Use Lion Sora’s tools rather than planning a Drive transformation.', 'Leave a quiet closing chapter for Spooky Cave.'],
  ['Meet the Pride Rock characters and investigate the recurring Scar image.', 'Track the hyenas through the required areas and complete their chase encounters.', 'Follow Simba’s crisis and decision to face the threat.', 'Enter the Savannah and fight Groundshaker through both its ground and back phases.', 'Watch the Pride Lands resolution and confirm Thundaga.', 'Visit Merlin and finish the Spooky Cave search in Pooh’s book.'],
  ['Simba’s doubt, the Scar images, and his recommitment.', 'The Groundshaker aftermath and family resolution.', 'Spooky Cave’s reunion with Pooh.'],
  [['Groundshaker','Use the opening reaction sequence to survive its huge attacks. Once on top, target the active threat and reposition when the platform becomes unsafe. Keep healing available for the return to the ground.']],
  ['Explain how the scale of the boss changes movement and target selection.'], 'Thundaga for Atlantica’s finale; Spooky Cave completion.'],
24: ['Olympus Coliseum second story visit.',
  ['Have a summon available and understand the damage-point rules for the cup afterward.', 'Keep Auron’s memory scenes intact.'],
  ['Enter the tournament storyline and notice Auron acting under Hades’ control.', 'Complete the required tournament and investigation beats.', 'Go to Hades’ Chamber, retrieve the statue, and watch the memories it contains.', 'Return to Auron and continue the Hercules/Meg resolution.', 'Defeat Hades in the Underdrome and watch the farewell.', 'Enter the ordinary Titan Cup and finish all ten rounds.'],
  ['Auron’s controlled behavior and the memories in the statue.', 'Hercules proving himself and Meg’s rescue.', 'Auron’s farewell and the world ending.'],
  [['Hades','Use Hercules’s aura spheres to remove invulnerability before attacking. Do not spend resources trying to brute-force the invulnerable state.'],['Titan Cup','Limit damage taken to preserve points, use Summons for support, and treat the Hercules finale as a defensive fight rather than a damage race.']],
  ['Discuss what makes Hercules a hero after the action, not during the central exchange.'], 'Guardian Soul; Titan Cup completion.'],
25: ['Hollow Bastion’s computer-system emergency.',
  ['Restock before entering the computer; put Tron in the party where required.', 'Use a save before the final computer-room sequence.'],
  ['Clear the town’s computer-controlled enemies and reach Merlin’s House for the situation report.', 'Cross the hostile defense system to Ansem’s Study.', 'Enter the Pit Cell and rejoin Tron.', 'Follow the system route and survive the Solar Sailer’s enemy waves before its capacity limit fails.', 'Reach the Central Computer and battle Sark.', 'Continue through giant Sark and the MCP, using Tron’s cooperation to finish.', 'Watch the entire Radiant Garden name reveal and the friends’ reunion.'],
  ['The town emergency and Cid’s solution.', 'Tron’s determination before the MCP fight.', 'The restored system, Radiant Garden, and Tron’s farewell.'],
  [['Solar Sailer','Clear heavy threats quickly and control groups before the load becomes critical.'],['Sark / MCP','Handle Sark to open access, break through the MCP defenses, and use Tron’s delete reaction. Repeat the cycle rather than attacking a protected core.']],
  ['Connect the restored name to the Restoration Committee’s work.'], 'Space Paranoids II completion: one of the Hades Paradox requirements.'],
26: ['Merlin’s House with all five Torn Pages recovered.',
  ['Check each world’s completed story markers; repair any missed page pickup now.', 'Confirm Thundaga from Groundshaker before traveling to Atlantica.'],
  ['Enter Pooh’s book and play the final Starry Hill chapter.', 'Watch the complete restoration of Pooh’s memories and the book’s ending.', 'Travel to Atlantica and complete A New Day Is Dawning.', 'Keep the ending dialogue and world completion, rather than cutting straight to the reward.', 'Show a short build audit: Forms, Summons, healing shortcuts, defensive abilities, and available equipment.', 'Demonstrate only a short sample of preparation; perform repetitive training between sessions.', 'Land at Twilight Town and stage the final mansion investigation.'],
  ['Pooh’s promise and the book’s final illustration.', 'Atlantica’s final song and story ending.', 'Any newly triggered travel scenes on the return to Twilight Town.'],
  [['Story minigames','Complete each required clear once. This chapter has no conventional boss; the world endings are its payoff.']],
  ['Explain why finishing these stories matters before the cleared-game save.', 'Recap the Kairi/Riku clues before returning to the main plot.'], '100 Acre Wood and Atlantica fully cleared; no score medals required.'],
27: ['Twilight Town: The Usual Spot, before the last mansion investigation.',
  ['Stock recovery items for Roxas and equip Guard, Reflect, and Limit Form support.', 'Do not plan to learn Final Form before the Roxas encounter.'],
  ['Meet the Twilight Town friends and investigate the Old Mansion.', 'Clear the mansion Nobodies and follow the computer-room clues.', 'Enter the alternate town and continue into Betwixt and Between.', 'Fight alongside Axel and keep his full final sequence.', 'Enter the Dark City through the new passage.', 'Advance to Memory’s Skyscraper and defeat Roxas.', 'Watch the complete aftermath, receive Two Become One, and continue to the Brink of Despair save.'],
  ['The friends uncovering the other town.', 'Axel’s sacrifice and the passage opening.', 'The complete Roxas duel framing and its aftermath.'],
  [['Roxas','Guard the readable combo strings and punish the recovery. Disengage when retaliation begins; long, unplanned combos can turn your opening into his. Use Limit Form for recovery when needed and learn the duel prompt.']],
  ['Pause the recap until after Axel’s scene finishes.', 'Compare this meeting with the Roxas the audience controlled in Parts 1–3.'], 'Two Become One; Final Form becomes obtainable after this fight.'],
28: ['The Brink of Despair after Roxas.',
  ['Unlock Final Form with Two Become One before serious Form training; show the success, not every repeated attempt.', 'Restock at the castle save before the boss chain.'],
  ['Demonstrate Final Form’s first successful appearance and explain its Nobody-based experience.', 'Cross the bridge into the castle and climb the lower rooms.', 'Watch Kairi and Naminé’s escape scenes and the party’s pursuit.', 'Reach the Hall of Empty Melodies and defeat Xigbar.', 'Continue through the reunions and upper castle route.', 'Enter Luxord’s confrontation and complete his game.', 'Backtrack to Twilight’s View to save before Saïx.'],
  ['Kairi/Naminé’s escape, Xigbar’s taunts, and the reunions.', 'Riku’s appearance and the emotional recognition.', 'Luxord introducing the game and his defeat.'],
  [['Xigbar','Guard or return shots, relocate when the arena changes, and respect the long barrage before retaliating.'],['Luxord','Read the command-menu game rather than mashing. Track the time gauge and learn the final card sequence; ordinary HP-race habits are insufficient.']],
  ['Explain Final Form after the dramatic scene, not over it.', 'Let Kairi and Riku’s reunion dialogue play without prediction commentary.'], 'Final Form unlocked; retain the castle’s story equipment rewards.'],
29: ['Twilight’s View after Luxord.',
  ['Re-equip recovery items and review the defensive build before climbing.', 'Plan a long story chapter plus a short cup epilogue.'],
  ['Return to the upper castle and confront Saïx.', 'Continue through the route to Ansem the Wise’s machine.', 'Watch the machine’s failure and Riku’s restoration in full.', 'Reach the Altar of Naught and defeat the first Xemnas encounter.', 'After the final door becomes available, save and leave for Olympus.', 'Clear every Goddess of Fate Cup round, including its changing restrictions.', 'Return to the Altar of Naught and save without entering the final door.'],
  ['Saïx’s confrontation and defeat.', 'Ansem the Wise’s conclusion and Riku regaining his appearance.', 'Xemnas’s first defeat and the final door opening.'],
  [['Saïx','Avoid trading during Berserk. Use dropped weapons and the reaction opportunities to interrupt it, then spend your damage window.'],['Xemnas I','Respond to the curse and building sequence; watch the reaction timing rather than pressing as early as possible. Guard his blade strings and punish the end.'],['Goddess of Fate','Read each new round’s restriction. Preserve MP and health for Hades instead of assuming every round uses the same rules.']],
  ['Explain why the cup detour happens before the point of no return.'], 'Goddess of Fate clear; all ordinary cups completed.'],
30: ['The Altar of Naught, ready to enter the final door.',
  ['Create a separate pre-finale save and stock Sora and Riku.', 'Reserve a long session: all final phases, ending scenes, and credits remain in.', 'Check every world story is complete before the cleared-game save.'],
  ['Enter the final door and complete the fortress assault and energy-core objectives.', 'Defeat the first armored encounter and keep the apparent conclusion.', 'Continue with Sora and Riku through the dragon battle.', 'Finish the subsequent armored sequence and enter the final Xemnas duel.', 'Complete the rescue and laser-defense mechanics to win.', 'Watch the Dark Margin, letter, homecoming, credits, and any unlocked ending scene in full.', 'Create the completed-game save when prompted and reload it.', 'Show the reloaded Altar of Naught and establish the optional-boss campaign.'],
  ['Every transition within the final boss chain.', 'Sora and Riku on the Dark Margin and Kairi’s letter.', 'The complete homecoming, credits, and naturally unlocked post-credits scenes.'],
  [['Final Xemnas chain','Treat each phase as a fresh encounter. Equip Riku before entering; when control switches during the rescue, move and use his ranged response to reach Sora. In the laser finale, use both required defensive inputs.']],
  ['Keep reactions live, then give a short story reflection after the credits.', 'Do not promise the extra secret movie that requires completion tasks outside this run.'], 'Completed-game save; final-world Data portals can now be available.'],
31: ['Completed-game save; travel to Olympus for the Silhouette circuit.',
  ['Equip Guard, Reflect, Cure, and useful movement abilities; bring recovery items.', 'This is a five-fight feature with travel breaks. Save after every victory.', 'Have all five portals’ story triggers cleared before starting.'],
  ['At Olympus, enter Zexion’s portal in Cave of the Dead: Inner Chamber; defeat him and save.', 'Travel to Twilight Town’s Sandlot and defeat Lexaeus; save at The Usual Spot.', 'Land at Agrabah’s Peddler’s Shop and defeat Vexen.', 'Sail to Port Royal’s Isla de Muerta and enter Larxene’s portal at Rock Face.', 'Finish at Beast’s Castle: enter the portal in The Beast’s Room and defeat Marluxia.', 'Confirm five cleared Silhouettes and retain each first-victory reward screen.'],
  ['Keep each portal’s first-entry introduction and victory transition.', 'Explain the Castle Oblivion connection using only events already known before Days.'],
  [['Zexion','Recognize the book dimension, locate the real target, and use the escape command when exposed. Read altered menu commands before selecting.'],['Lexaeus','Guard the heavy strings and exploit the reaction opportunity; his power meter makes reckless trades costly.'],['Vexen','Avoid standing in the tracking circle. Break the shield and manage the summoned copy before it overwhelms the arena.'],['Larxene','Use Reflect against committed multi-hit approaches and exploit the clone-related reaction when offered.'],['Marluxia','The curse is a separate hit counter. Learn the counter-restoring reaction, avoid floor hazards, and do not confuse healing HP with restoring the counter.']],
  ['Introduce one mechanic per fight and compare the five styles in the closing recap.'], 'All five Silhouette clears; their Data rematches unlocked.'],
32: ['Radiant Garden: Crystal Fissure before visiting Dark Depths.',
  ['Equip Second Chance and Once More if learned, level-3 movement, and reliable recovery.', 'Bring a stock of recovery items; practice may take much longer than the final episode.', 'Keep your normal boss Keyblade available for comparison with Fenrir.'],
  ['Show a concise loadout and explain your recovery plan.', 'Enter Dark Depths and speak to Sephiroth to start the encounter.', 'Keep a few different learning attempts, then the complete successful fight.', 'After victory, speak to Sephiroth again and report his location to Cloud at the Marketplace.', 'Return to Dark Depths for the Cloud/Tifa sequence.', 'Receive Fenrir and save at Crystal Fissure.'],
  ['Sephiroth’s challenge and post-victory dialogue.', 'Cloud and Sephiroth’s confrontation and Tifa’s conclusion.'],
  [['Sephiroth','React immediately to the opening command. Guard the ground strings, reposition against the fire pillars, and interrupt Heartless Angel when reachable. Keep an item recovery fallback. Limit Form is available without party members and can rescue a failing attempt.']],
  ['Explain one adjustment between attempts instead of replaying identical losses.', 'Show why Fenrir is a specialized tool rather than an automatic upgrade for every fight.'], 'Fenrir; Sephiroth cleared.'],
33: ['Olympus Coliseum, with all ordinary cups cleared.',
  ['Finish Form/Summon training before the recording: all five Forms at level 7 and shared Summon level 7 is this route’s preparation target.', 'Confirm Chicken Little, Genie, Stitch, and Peter Pan are available.', 'Speak to Hades in his chamber for Paradox cups, not the ordinary-cup attendants.'],
  ['Show the cup clear list and the Form/Summon status screens.', 'Clear Pain and Panic Paradox, including Leon and Yuffie.', 'Return to Hades and clear Cerberus Paradox within its time limit.', 'Return once more and clear Titan Paradox while preserving damage points.', 'Show Hades Paradox selectable and save at the Underworld Entrance.'],
  ['Retain the first-time cup introductions, result screens, and any triggered world dialogue.'],
  [['Pain and Panic Paradox','Use the reduced-cost party Limits to control dangerous combinations.'],['Cerberus Paradox','Use the cup’s Drive recovery and aggressive magic to avoid losing to the timer.'],['Titan Paradox','Support yourself with Summons and avoid repeated hits; remaining HP alone does not determine survival.']],
  ['Use the three cups to teach the three rule sets that return in the marathon.'], 'First three Paradox cups cleared; Hades Paradox available.'],
34: ['Hades’ Chamber with Hades Paradox unlocked.',
  ['Allow one longer tournament special with five clearly labeled ten-round chapters.', 'No 15,000-point journal target is required.', 'Use the ten-round restart checkpoints for a break if needed; save outside the cup and record the restart round.'],
  ['Clear rounds 1–10 under the opening rules; keep Volcanic Lord and the Yuffie/Tifa finale.', 'Clear rounds 11–20 while protecting the damage-point allowance; finish Pete.', 'Clear rounds 21–30 using party Limits where permitted; show Cloud/Tifa and Hades.', 'If taking a break, exit only after the checkpoint is earned and verify the next starting round with Hades.', 'Resume rounds 31–40, beat the timed Nobody waves, and defeat Leon/Cloud.', 'Survive the final solo block; keep round 45’s survival challenge.', 'Defeat Cerberus at 48 and all four Final Fantasy opponents at 49.', 'Defeat Hades at 50, show the trophy, and save outside the tournament.'],
  ['Keep the cup entry and results; do not turn the named-opponent rounds into a montage.'],
  [['Rounds 1–30','Adapt when the rules change: normal toolkit, then damage-point conservation with Summons, then efficient party Limits.'],['Rounds 31–40','Final Form and group magic help beat the timer. Sorcerers require appropriate physical damage rather than elemental spam.'],['Rounds 41–50','Limit Form is the recovery option in Final Mix’s solo block. Keep the four opponents visible at 49, isolate safe punish windows, and use Hercules’s aura spheres against Hades.']],
  ['Announce each rule change and the next checkpoint so the long episode has clear acts.'], 'Hades Paradox Cup cleared; no journal score grinding.'],
35: ['Radiant Garden: Postern, outside the Cavern entrance.',
  ['Equip High Jump 3, Quick Run 3, Aerial Dodge 3, and Glide 3; Dodge Roll 3 is useful for combat.', 'Finish training beforehand and stock recovery items for a long run without convenient saves.', 'Use Magnet and Reflect, but keep a physical option against Sorcerers.'],
  ['Enter the hole at the Postern and traverse the Depths.', 'Use Quick Run through the first Mineshaft movement gate; clear its required enemy battle.', 'Activate the Mining Area machinery and climb its moving platforms.', 'Use Aerial Dodge for the next Mineshaft passage.', 'Cross the Engine Chamber’s belts, pistons, and steam hazards.', 'Use Glide to thread the final Mineshaft obstacle.', 'Clear all three multi-wave Transport to Remembrance encounters.', 'Enter the Garden, inspect all thirteen portals, and open the shortcut behind the computer.', 'Exit to the Restoration Site, continue to the Postern, and save.'],
  ['Keep the first entrance and the Garden reveal. There is little conventional story dialogue; the discovery is the payoff.'],
  [['Transport to Remembrance','Control crowds before being surrounded, identify high-priority enemies, and use defensive tools rather than trying to air-combo every wave. Save resources for later waves; the third encounter is not a victory lap.']],
  ['Name the movement ability at each gate so viewers see the purpose of Form training.'], 'Garden shortcut open. No Data victory scheduled in this episode.'],
36: ['Postern → Restoration Site shortcut → Garden of Assemblage.',
  ['Restock and equip defensive abilities before entering.', 'Treat each fight as a complete segment with setup, learning, victory, and a save.', 'After the first win, take the shortcut and save at the Postern before attempting the next.'],
  ['Inspect Xigbar’s portal and explain your projectile-defense plan.', 'Record the full successful Data Xigbar fight.', 'Exit to save and reconfigure for Luxord.', 'Explain Luxord’s time gauge and command games before starting.', 'Defeat Data Luxord and show both cleared portals.', 'Return to the Postern and save: 2 of 13 Data battles cleared.'],
  ['Keep both first-entry introductions and defeat transitions, even if the footage echoes the story fights.'],
  [['Data Xigbar','Guard returned shots deliberately, reposition when the arena shrinks, and wait out the extended barrage before punishing. Avoid healing into an incoming volley.'],['Data Luxord','Prioritize correct games over ordinary damage. Practice command selection, read the final challenge, and do not let frustration turn inputs into random mashing.']],
  ['Contrast a reflex-and-positioning fight with a rules-and-timing fight.'], 'Data Xigbar and Luxord cleared; 2/13.'],
37: ['Garden of Assemblage, after two Data wins.',
  ['Equip a magic-focused setup with Ethers and Fire support.', 'Plan on Wisdom Form Firaga for Demyx’s clones.', 'Save between the two bosses and restock if the learning attempts consumed items.'],
  ['Show Vexen’s shield and tracking-circle mechanics in a brief setup.', 'Learn the safe shield-break opening and manage the summoned copy.', 'Defeat Data Vexen and save via the Postern.', 'Switch to the Demyx-specific magic setup.', 'Clear every water-clone timer and finish the complete Data Demyx encounter.', 'Save with four cleared Data portals.'],
  ['Keep first-entry and victory scenes for both rematches.'],
  [['Data Vexen','Keep moving out of the tracking circle, break the shield, and punish with Fire when safe. Do not ignore the copy while chasing the main boss.'],['Data Demyx','Use Wisdom Firaga to erase water forms quickly, manage MP between checks, and make sure the right party member is available for Wisdom. Timed phases can end an otherwise healthy attempt.']],
  ['Show the actual loadout change so the audience understands why a general boss build is insufficient.'], 'Data Vexen and Demyx cleared; 4/13.'],
38: ['Garden of Assemblage, after four Data wins.',
  ['Keep Guard, Reflect, and recovery on familiar inputs.', 'Review armor for Larxene’s lightning pressure.', 'Preserve a save between victories.'],
  ['Start with Lexaeus and explain the power gauge.', 'Record a useful defensive adjustment, then the full successful fight.', 'Save and change equipment for Larxene.', 'Demonstrate reading her approach rather than chasing every teleport.', 'Defeat her and update the six-fight checklist.'],
  ['Retain both portal introductions and victory transitions.'],
  [['Data Lexaeus','Avoid head-on damage trades. Guard the heavy strings, take the reaction counter when offered, and exploit the opening without overstaying.'],['Data Larxene','Reflect committed multi-hit approaches, keep clones within your view, and capitalize on the reaction opportunity. Heal after creating space rather than between unsafe hits.']],
  ['Use one slow, heavy opponent and one fast opponent to explain the same defensive principle.'], 'Data Lexaeus and Larxene cleared; 6/13.'],
39: ['Garden of Assemblage, after six Data wins.',
  ['Review escape and reaction commands before each attempt.', 'Do not mistake high HP for safety against special failure conditions.', 'Save at the Postern after the first victory.'],
  ['Enter Zexion’s portal and explain the book dimension.', 'Work through the altered commands and escape cycles until the complete victory.', 'Save and set up for Marluxia.', 'Show the curse counter, floor hazards, and counter-restoring reaction.', 'Defeat Marluxia and confirm all five Castle Oblivion Data opponents are complete.'],
  ['Keep each rematch’s introduction and ending.'],
  [['Data Zexion','Find the real target, expose the escape command, and react to the safe-zone sequence. Read the command menu when it changes instead of assuming Attack is still Attack.'],['Data Marluxia','Avoid unnecessary hits that drain the curse. Choose the appropriate reaction to recover the counter, reposition around the floor patterns, and punish only after the dangerous sequence ends.']],
  ['Explain the failure condition before the successful fight so viewers can follow the stakes.'], 'Data Zexion and Marluxia cleared; 8/13.'],
40: ['Garden of Assemblage, after eight Data wins.',
  ['Keep healing and Limit Form recovery available.', 'Know Axel’s required reaction sequence before the final successful attempt.', 'Plan a save and short recap between fights.'],
  ['Enter Axel’s portal and establish the burning-floor problem.', 'Use his reaction sequence and finish the whole encounter.', 'Save at the Postern, then return for Saïx.', 'Track Saïx’s Berserk state and create a controlled punish window.', 'Defeat him and save with ten Data wins.'],
  ['Keep Axel and Saïx’s first-entry and victory sequences.'],
  [['Data Axel','Manage the burning arena with his reaction sequence. Follow it through to the proper finishing opportunity; damage alone is not a substitute for resolving the mechanic.'],['Data Saïx','Avoid repeated hits during Berserk, recover the dropped weapon, and use the disruption opportunity. Do not spend the opening on an uncontrolled combo that invites retaliation.']],
  ['Discuss Axel’s presentation without revealing the Days story you will watch afterward.'], 'Data Axel and Saïx cleared; 10/13.'],
41: ['Garden of Assemblage, after ten Data wins.',
  ['Stock recovery items and allow substantial learning time.', 'Choose consistent defensive abilities over an experimental damage-only setup.', 'Save after Roxas before moving to Xaldin.'],
  ['Enter Roxas’s rematch and demonstrate the defensive plan.', 'Show one meaningful improvement, then the full victory.', 'Return to the Postern to save and restock.', 'Revisit Xaldin’s Learn/Jump mechanic and his wind barrier.', 'Defeat Data Xaldin and show Xemnas as the only remaining portal.'],
  ['Retain both rematch introductions and defeat sequences.'],
  [['Data Roxas','Guard the strings, punish a reliable recovery, and stop attacking when retaliation starts. React to the duel and respect the light-based attacks rather than forcing an extra combo.'],['Data Xaldin','Stock Learn/Jump opportunities, avoid swinging into the barrier, and use movement for the wind attack. Keep recovery in reserve for a failed dodge.']],
  ['Compare your control here with the two original story encounters.'], 'Data Roxas and Xaldin cleared; 12/13.'],
42: ['Garden of Assemblage, with only Xemnas remaining.',
  ['Equip both Sora and Riku and restock before entering.', 'Allow for two distinct battles and keep the entire successful sequence.', 'Do not leave without collecting the all-Data reward chest.'],
  ['Show the twelve cleared portals and the final loadout.', 'Defeat the first Data Xemnas phase, including the curse/building sequence.', 'Complete the final-form rematch with Riku.', 'Keep the rescue and laser finale on-screen through victory.', 'Return to the Garden, verify all thirteen clears, and open the reward chest.', 'Collect the Proof of Nonexistence and save at the Postern.'],
  ['Both Xemnas rematch introductions, transitions, and conclusions.', 'The Garden reward reveal after all thirteen victories.'],
  [['Data Xemnas','Respond to the curse, time the building reaction, and punish blade-string recovery. In the final fight, prepare for Riku’s rescue control and both laser-defense inputs. Do not use the story victory as proof that the stronger rematch is safe to rush.']],
  ['Give the Data campaign its own conclusion before moving to the last superboss.'], 'All 13 Data rematches; Proof of Nonexistence.'],
43: ['Disney Castle Library → Hall of the Cornerstone.',
  ['Confirm the completed-game world clears and the portal’s availability.', 'Equip level-3 movement, Once More, Second Chance, and a stocked recovery setup.', 'Set aside multiple practice sessions if needed; the final video is not a promise of a first-try clear.'],
  ['Show the completed Silhouette, Sephiroth, cup, and Data checklist.', 'Enter the portal and watch the armor’s entire introduction.', 'Identify the opening pattern and establish a safe defense before trying long punish strings.', 'Keep a few distinct learning moments, then the complete successful Lingering Will fight.', 'Watch the victory aftermath and collect the Proof of Connection.', 'Return to the Library, save, and close the playable KH2FM campaign.', 'Introduce the final two episodes as the 358/2 Days HD movie watch.'],
  ['The portal arrival, armor’s dialogue, and full post-victory scene.', 'A short series recap after returning safely to the Library.'],
  [['Lingering Will','Read each weapon transformation and defend before punishing. Recognize command seals and resolve their condition. Keep combos controlled to avoid retaliation; prioritize survival during the desperation sequence. Use Limit Form as a recovery plan, not an excuse to ignore tells.']],
  ['Finish all playable boss business before the movie chapters.', 'Keep speculation about Terra and other games separate from what KH2FM actually shows.'], 'Proof of Connection; every required optional boss complete before Days.'],
44: ['Collection launcher → Kingdom Hearts 358/2 Days → the beginning of the HD movie.',
  ['This is the HD cinematic collection, not a DS gameplay walkthrough or a fan-edit compilation.', 'Enable subtitles and test game/dialogue audio against your microphone.', 'Record the whole watch; pause for longer comments instead of talking over dialogue.'],
  ['Introduce the watch as a look back at Roxas’s life before KH2; all KH2FM bosses are already finished.', 'Start the movie from the opening, including the opening credits and initial flash-forward.', 'Watch in the collection’s presented order rather than trying to sort the day numbers chronologically.', 'Keep all narration and interstitial text readable between scenes.', 'Follow the formation of the trio and changes in their everyday routine; take short reaction breaks at chapter boundaries.', 'Continue through the complete Day 193 group of scenes.', 'End after The Girl with the Sketch Book, before the Day 194~ section begins.', 'Record the exact chapter label in your notes so the next episode resumes without a gap.'],
  ['Every scene and text bridge from the opening through the final Day 193 scene.', 'Do not skip the early Day 255 flash-forward just because that day returns later.'],
  [['Watch session — no playable bosses','Keep any on-screen confrontations as part of the movie. Do not add DS missions or boss fights that the HD movie does not let you play.']],
  ['Track what each friend knows without reading ahead in the reports.', 'Compare Roxas’s behavior with the prologue you recorded, then let the film answer the next question.'], 'Bookmark: after Day 193, The Girl with the Sketch Book. Use chapter selection on resume; do not rely on a suspended console session.'],
45: ['358/2 Days HD movie → Day 194~: Axel Learns the Truth.',
  ['Use the exact collection chapter bookmark from Part 44, not a guessed YouTube timestamp.', 'Budget the longest watch session for the late story, ending, and reflection.', 'Keep later reports/character files optional until the full movie has finished.'],
  ['Open with a brief recap, then resume at the first Day 194~ scene.', 'Watch every remaining scene and text bridge in the collection’s order.', 'Pause only at natural breaks for commentary; preserve complete conversations and confrontations.', 'Let the late-story revelations and final battles play before giving your interpretation.', 'Continue through Day 359 and the ending credits.', 'Give a closing reflection connecting the film to Roxas’s summer, Axel, and Sora’s awakening.', 'Return to the Chapters/menu screen and mark the two watch episodes complete.'],
  ['All remaining movie chapters from Day 194~ through Day 359.', 'The full ending and credits, including any extended scenes present in your edition.'],
  [['Watch session — no playable bosses','The movie includes late-story confrontations; these are viewed scenes, not additional KH2FM boss objectives. All required playable bosses were completed by Part 43.']],
  ['Discuss how the film changes your reading of the KH2 prologue.', 'Close the full 45-episode series here; do not end before the credits to hit a time target.'], 'Full HD movie watched; finish at the Chapters/menu screen.']
};

const KH_EPISODES = Array.from({length:45}, (_, index) => {
  const id=index+1;
  let base;
  if(id<=30) base=ORIGINAL_EPISODES[id-1];
  else if(id===31) base={...ORIGINAL_EPISODES[30],title:'The Five Absent Silhouettes',world:'Olympus → Twilight Town → Agrabah → Port Royal → Beast’s Castle',stop:'The Beast’s Room save point, after all five Silhouette victories.'};
  else if(id===34) base={...ORIGINAL_EPISODES[34],title:'Hades Paradox Cup — All 50 Rounds',stop:'Underworld Entrance save point, after the round-50 Hades victory and trophy.'};
  else if(id<44) base={...ORIGINAL_EPISODES[(id<34?id+1:id+2)-1],...(id===43?{stop:'Disney Castle Library save point after Lingering Will. Close the KH2FM boss campaign; the next episode begins the Days movie.'}:{})};
  else base={title:id===44?'358/2 Days — Roxas, Axel, and Xion':'358/2 Days — The Friends We Remember',world:'Kingdom Hearts 358/2 Days · HD cinematic collection',stop:id===44?'Pause after Day 193’s The Girl with the Sketch Book, before Day 194~. Record the chapter bookmark for resume.':'After Day 359 and the complete credits, return to the Chapters/menu screen.'};
  // Surface the musical visits in the current route without rewriting the
  // original episode archive used for old-progress migration.
  if(id===11) base={...base,title:'Atlantica — Swim This Way, Then Port Royal',world:'Atlantica → Port Royal'};
  if(id===16) base={...base,title:'Tron and Atlantica — Under the Sea'};
  if(id===22) base={...base,title:'The Experiment and Atlantica — Ursula’s Revenge'};
  if(id===26) base={...base,title:'Pooh and Atlantica — A New Day Is Dawning'};
  const [start,prep,objectives,cutscenes,tactics,commentary,pickups]=DETAILS[id];
  const [editedMin,editedMax,recordingMin,recordingMax]=FULL_SCENE_TIMES[index];
  return {...base,id,kind:id>=44?'watch':id<=30?'story':'endgame',start,prep,objectives,cutscenes,tactics,commentary,pickups,encounters:tactics.map(([name,text])=>`${name}: ${text}`).join(' '),timing:{editedMin,editedMax,recordingMin,recordingMax}};
});
